  if(SEMANA_ACTIVA){nuevo.tipo=v.tipo;if(v.oculto)nuevo.oculto=true;else delete nuevo.oculto;if(v.oculto&&v.hs!=null)nuevo.hs=v.hs;else delete nuevo.hs}
